// Prepare calendar URLs for fetching
const property = $input.item.json;
const calendars = [];

if (property.airbnb_calendar_url && property.airbnb_calendar_url.length > 10) {
  calendars.push({
    platform: 'airbnb',
    url: property.airbnb_calendar_url,
    property_id: property.property_id,
    property_name: property.property_name
  });
}
if (property.vrbo_calendar_url && property.vrbo_calendar_url.length > 10) {
  calendars.push({
    platform: 'vrbo',
    url: property.vrbo_calendar_url,
    property_id: property.property_id,
    property_name: property.property_name
  });
}

if (calendars.length === 0) {
  return {
    skip: true,
    property_id: property.property_id,
    message: 'No valid calendar URLs'
  };
}

return calendars[0]; // Return first calendar for now

// Parse iCal data and extract events with error handling
try {
  const input = $input.item.json;
  const icalData = typeof input === 'string' ? input : (input.data || input.body || '');
  const urlData = $('Prepare Calendar URLs').item.json;
  const property_id = urlData.property_id;
  const platform = urlData.platform;

  if (!icalData || icalData.length < 20) {
    return {
      property_id: property_id,
      platform: platform,
      events_count: 0,
      events: [],
      error: 'No valid iCal data received',
      synced_at: new Date().toISOString()
    };
  }

  const events = [];
  const lines = icalData.split(/\r?\n/);
  let currentEvent = null;

  for (const line of lines) {
    if (line.startsWith('BEGIN:VEVENT')) {
      currentEvent = {};
    } else if (line.startsWith('END:VEVENT') && currentEvent) {
      if (currentEvent.dtstart && currentEvent.dtend) {
        events.push({
          property_id: property_id,
          platform: platform,
          external_id: currentEvent.uid || `${platform}_${Date.now()}_${events.length}`,
          summary: currentEvent.summary || 'Blocked',
          check_in: currentEvent.dtstart,
          check_out: currentEvent.dtend,
          description: currentEvent.description || ''
        });
      }
      currentEvent = null;
    } else if (currentEvent) {
      const colonIdx = line.indexOf(':');
      if (colonIdx > 0) {
        const key = line.substring(0, colonIdx);
        const value = line.substring(colonIdx + 1);

        if (key.startsWith('DTSTART')) {
          currentEvent.dtstart = value.replace(/T.*/, '').replace(/[^0-9-]/g, '');
          if (currentEvent.dtstart.length === 8) {
            currentEvent.dtstart = currentEvent.dtstart.substring(0,4) + '-' + currentEvent.dtstart.substring(4,6) + '-' + currentEvent.dtstart.substring(6,8);
          }
        } else if (key.startsWith('DTEND')) {
          currentEvent.dtend = value.replace(/T.*/, '').replace(/[^0-9-]/g, '');
          if (currentEvent.dtend.length === 8) {
            currentEvent.dtend = currentEvent.dtend.substring(0,4) + '-' + currentEvent.dtend.substring(4,6) + '-' + currentEvent.dtend.substring(6,8);
          }
        } else if (key === 'UID') {
          currentEvent.uid = value;
        } else if (key === 'SUMMARY') {
          currentEvent.summary = value;
        }
      }
    }
  }

  return {
    property_id: property_id,
    platform: platform,
    events_count: events.length,
    events: events.slice(0, 50), // Limit to 50 events
    synced_at: new Date().toISOString()
  };
} catch (err) {
  return {
    property_id: $('Prepare Calendar URLs').item.json.property_id,
    platform: $('Prepare Calendar URLs').item.json.platform,
    events_count: 0,
    events: [],
    error: err.message,
    synced_at: new Date().toISOString()
  };
}

// Prepare result for this property
const data = $json;

return {
  property_id: data.property_id,
  platform: data.platform,
  events_synced: data.events_count || 0,
  success: !data.error,
  error: data.error || null,
  synced_at: data.synced_at
};

// No properties to sync
return {
  success: true,
  message: 'No properties with calendar integrations found',
  timestamp: new Date().toISOString()
};
